// 键盘通道手动验收：iChannel0 = 256x2 键盘数据纹理（KB）
// row0 = 本帧按下边沿（keydown 后首帧为 255，随即清零）
// row1 = 按下锁存（按下期间保持 255，松开/移出画布清零）
void mainImage(out vec4 o, in vec2 f) {
    vec2 uv = f / iResolution.xy;

    float pulseA = texelFetch(iChannel0, ivec2(65, 0), 0).x; // 'A' 本帧按下
    float latchA = texelFetch(iChannel0, ivec2(65, 1), 0).x; // 'A' 锁存
    float latchD = texelFetch(iChannel0, ivec2(68, 1), 0).x; // 'D' 锁存

    vec3 col = vec3(0.05, 0.07, 0.10);

    // A 按住：左半屏泛蓝；D 按住：右半屏泛绿
    col += vec3(0.00, 0.22, 0.55) * latchA * smoothstep(0.55, 0.10, uv.x);
    col += vec3(0.00, 0.45, 0.18) * latchD * smoothstep(0.45, 0.90, uv.x);

    // A 按下瞬间：全屏白闪一帧（边沿）
    col += vec3(pulseA);

    // 顶部计数条：统计 A-Z 锁存数量
    float held = 0.0;
    for (int c = 65; c < 91; c++) held += texelFetch(iChannel0, ivec2(c, 1), 0).x;
    col += vec3(0.95, 0.85, 0.20) * step(0.5, held) * 0.10 * smoothstep(0.85, 0.0, uv.y);

    o = vec4(col, 1.0);
}
